        address target,
        uint256 value,
        bytes calldata payload,
        bytes32 salt
    ) external payable whenNotPaused {
        ---SNIP---

        _execute(target, value, payload);
        ---SNIP---
    }
```
[`executeBatch()`](https://github.com/code-423n4/2024-10-kleidi/blob/ab89bcb443249e1524496b694ddb19e298dca799/src/Timelock.sol#L621-L650):
```solidity
    function executeBatch( //@audit
        address[] calldata targets,
        uint256[] calldata values,
        bytes[] calldata payloads,
        bytes32 salt
    ) external payable whenNotPaused {

        ---SNIP---
        for (uint256 i = 0; i < targets.length; i++) {
            bytes calldata payload = payloads[i];

            _execute(targets[i], values[i], payload);
            emit CallExecuted(id, i, targets[i], values[i], payload);
        }
        ---SNIP---    
    }
```
[`_execute()`](https://github.com/code-423n4/2024-10-kleidi/blob/ab89bcb443249e1524496b694ddb19e298dca799/src/Timelock.sol#L1021-L1026):
```solidity
    function _execute(address target, uint256 value, bytes calldata data) private {
>>      (bool success, ) = target.call{value: value}(data);
        require(success, "Timelock: underlying transaction reverted");
    }
```
**The Contract Holds Ether**:
The [`receive()`](https://github.com/code-423n4/2024-10-kleidi/blob/ab89bcb443249e1524496b694ddb19e298dca799/src/Timelock.sol#L1339-L1343) function allows the contract to receive and hold `ether` from any external source, including previous users or other contracts.
